import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"萃","description":"焦氏易林注 - 萃","frontmatter":{"title":"萃","description":"焦氏易林注 - 萃"},"headers":[],"relativePath":"classics/jiaoyilin/045.md","filePath":"classics/jiaoyilin/045.md"}'),l={name:"classics/jiaoyilin/045.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><h3 id="萃-1" tabindex="-1">萃 <a class="header-anchor" href="#萃-1" aria-label="Permalink to “萃”">​</a></h3><h3 id="萃之乾" tabindex="-1">萃之乾 <a class="header-anchor" href="#萃之乾" aria-label="Permalink to “萃之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>碩鼠四足，飛不上屋。顏氏淑德，未有爵祿。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>《說文》：鼫鼠五技，能飛不能上屋。此用萃象。艮為鼠，伏震為足，卦數四，故曰四足。艮為飛、為屋、為顏、為爵。○淑，汲古作淵，依宋元本。</p><h3 id="萃之坤" tabindex="-1">萃之坤 <a class="header-anchor" href="#萃之坤" aria-label="Permalink to “萃之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>新受大喜，福履重職，樂且日富。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>兌為悅，正反兌喜樂，坤為重，坤多，故曰富。仍用萃象。</p><h3 id="萃之屯" tabindex="-1">萃之屯 <a class="header-anchor" href="#萃之屯" aria-label="Permalink to “萃之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>克身潔已，逢禹巡狩。錫我玄龜，拜受福祉。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坤為身，坎水，故曰潔。震為王，故曰禹。艮為龜，震為玄，故曰玄龜。《書洪範》：天乃錫禹洪範九疇，註：天與禹洛出書，神龜負文而出，列於背，有數至九，禹因而第之以成九疇，故曰錫我玄龜，拜受福祉。艮為拜，震為祉。○克，宋元本作克，潔作整，依汲古。</p><h3 id="萃之蒙" tabindex="-1">萃之蒙 <a class="header-anchor" href="#萃之蒙" aria-label="Permalink to “萃之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>置筐失筥，輪破無輔。家伯為政，病我下土。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為筐筥，坎為失、為輪、為破、為家，震為伯，《詩小雅十月篇》：&quot;家伯冡宰&quot;，助幽王為虐者也。坎為病，坤為下土，《小雅》&quot;無棄爾輔&quot;註：輔以佐車。</p><h3 id="萃之需" tabindex="-1">萃之需 <a class="header-anchor" href="#萃之需" aria-label="Permalink to “萃之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>機言不發，頑不能達。齊魯為仇，亡我葵丘。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>此用《萃》象。兌為言，三至上正反兌，故曰機言，坤閉，故不發。艮止，故頑不能達。巽齊兌魯相背，故曰為仇。艮為丘，兌為華，故曰葵丘。</p><h3 id="萃之訟" tabindex="-1">萃之訟 <a class="header-anchor" href="#萃之訟" aria-label="Permalink to “萃之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>亡錐失斧，公輸無輔。抱其彞器，適君子處。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>坎為錐，坎失，故曰亡錐。兌為斧，兌覆，故曰失斧。巽為工，故曰公輸。兌為輔，兌折，故無輔。伏震為彞器。萃艮為抱、為君子，言微子抱彞適周也。兼用萃象。</p><h3 id="萃之師" tabindex="-1">萃之師 <a class="header-anchor" href="#萃之師" aria-label="Permalink to “萃之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>家在海隅，橈短深流。伯氏難行，無木以趨。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《蒙》。</p><h3 id="萃之比" tabindex="-1">萃之比 <a class="header-anchor" href="#萃之比" aria-label="Permalink to “萃之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>德施流行，利之四鄉。雨師灑道，風伯逐殃。巡狩封禪，以告成功。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《復》。</p><h3 id="萃之小畜" tabindex="-1">萃之小畜 <a class="header-anchor" href="#萃之小畜" aria-label="Permalink to “萃之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>筐傾筥覆，喪我公粒。簡伯無禮，太師正食。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為筐筥，二至四震覆，故曰傾覆。震為公、為粒、為竹簡、為伯，故實未詳。○粒，汲古作置，依宋元本。</p><h3 id="萃之履" tabindex="-1">萃之履 <a class="header-anchor" href="#萃之履" aria-label="Permalink to “萃之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>泥滓汙辱，棄捐溝瀆。為眾所笑，終不顯錄。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤水坎水，故曰泥滓汙辱。坤死，故曰棄捐。互坎故曰溝瀆。坎眾，震笑，艮為顯，在下故不顯。</p><h3 id="萃之泰" tabindex="-1">萃之泰 <a class="header-anchor" href="#萃之泰" aria-label="Permalink to “萃之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>獮猴兔足，腥臊少肉。漏巵盛酒，利無所有。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為獮猴、為兔、為足，伏巽為腥臊，兌為骸骨，故少肉。震為巵，伏巽，下斷故曰漏巵。兌為酒，與震連，故曰漏疤盛酒。巽為利，巽伏，故無利。○有，宋元本作得，非，依汲古。</p><h3 id="萃之否" tabindex="-1">萃之否 <a class="header-anchor" href="#萃之否" aria-label="Permalink to “萃之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>鹿畏人藏，俱入深谷。命短不長，為虎所得，死於牙腹。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《比》。</p><h3 id="萃之同人" tabindex="-1">萃之同人 <a class="header-anchor" href="#萃之同人" aria-label="Permalink to “萃之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>南山芝蘭，君子所有。東家淑女，生我玉寶。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為山，位南，故曰南山。巽為芝蘭，乾為君子，離為東家，巽為女，乾善，故曰東家淑女。乾為玉、為寶。○芝蘭，宋元本作蘭芝，依汲古。</p><h3 id="萃之大有" tabindex="-1">萃之大有 <a class="header-anchor" href="#萃之大有" aria-label="Permalink to “萃之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>左指右揮，邪佞侈靡。執節無良，靈君以亡。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。離東故曰左，坎西故曰右。艮為指揮，乾言，兌亦為言，而與乾背，故曰邪佞。離為文，故曰侈靡。艮為執、為節，乾為君，坤死，故曰靈君以亡。似指楚靈王。</p><h3 id="萃之謙" tabindex="-1">萃之謙 <a class="header-anchor" href="#萃之謙" aria-label="Permalink to “萃之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>鬱不明，為陰所傷。眾霧群聚，共奪日光。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為明，坎隱，故鬱不明。，日食色也。坤陰在上，故曰為陰所傷。坤為眾、為霧，故曰眾霧群聚。艮為日，坎黑，地黑，故曰光被奪也。○鬱，汲古作爵秩，陰作臣，霧作陰，依《噬嗑》之《艮》校。</p><h3 id="萃之豫" tabindex="-1">萃之豫 <a class="header-anchor" href="#萃之豫" aria-label="Permalink to “萃之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>穿鼻系株，為虎所拘。王母祝禱，禍不成災。突然脫來。互艮為鼻，</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為穿，故曰穿鼻。伏巽為系、為木，故曰系株。艮為虎，艮止，故為虎所拘。坤為母，震為王、為言，故曰王母祝禱。坎為禍災，震出在外，故脫去禍災也。○禱，元本作福，依宋元本、汲古。</p><h3 id="萃之隨" tabindex="-1">萃之隨 <a class="header-anchor" href="#萃之隨" aria-label="Permalink to “萃之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>貧鬼守門，日破我盆。毀罌傷缸，空虛無子。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《兌》。</p><h3 id="萃之蠱" tabindex="-1">萃之蠱 <a class="header-anchor" href="#萃之蠱" aria-label="Permalink to “萃之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>襄王叔帶，鄭人是賴。莊公卿士，王母憂苦。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互震為王，艮為叔，巽為帶，震為莊、為公，巽為母，互大坎為鄭、為憂苦。按：《左傳僖二十四年》：&quot;大叔帶以狄師伐周襄王，奔鄭，大叔居溫，鄭伯與鄭大夫每日省視，官具乾泛而後聽私政，叔帶亦依附鄭人&quot;，故曰襄王叔帶、鄭人是賴。王母似指隗氏。○叔，元本訛束，依宋本、汲古。苦，汲古作喜，依宋元本。王，宋元本作皇，依汲古。</p><h3 id="萃之臨" tabindex="-1">萃之臨 <a class="header-anchor" href="#萃之臨" aria-label="Permalink to “萃之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>昭君死國，諸夏蒙德。異類既同，宗我王室。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為君，坤為文，故曰昭君。坤為死、為國，昭君死國，言昭王南征不返也。坤為眾，故曰諸夏。震為德也。坤為類，伏艮為室，震為宗、為王。○死，汲古作守，依宋元本。宗，汲古作崇，依宋元本。</p><h3 id="萃之觀" tabindex="-1">萃之觀 <a class="header-anchor" href="#萃之觀" aria-label="Permalink to “萃之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>冬藪枯腐，常風於道。蒙被塵埃，左右勞苦。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為冬、為藪，《爾雅釋地》：&quot;藪，大澤也&quot;，藪至冬日蘆葦皆枯死，故曰冬藪枯腐。巽為枯腐、為風，艮為道路。常風於道，言枯腐之物常為風吹至道也。坤為塵埃，伏震為左，兌為右。○枯，汲古作朽，依宋元本。常，汲古作當，依宋元本。</p><h3 id="萃之噬嗑" tabindex="-1">萃之噬嗑 <a class="header-anchor" href="#萃之噬嗑" aria-label="Permalink to “萃之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>六爻既立，神明喜告。文定吉祥，康叔受福。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>坎數六，爻，交也。坎乾交坤，故曰六爻既立。左傳&quot;六體不易&quot;亦以六為坎。震為神、為喜告，離為明、為文。詩：文定厥祥，震為康，艮為叔。○喜，汲古作所，依宋元本。</p><h3 id="萃之賁" tabindex="-1">萃之賁 <a class="header-anchor" href="#萃之賁" aria-label="Permalink to “萃之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>泣涕長訣，我心不悅。遠送衛野，歸寧無咎。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎為泣涕、為心、為憂，故不悅。震為衛，艮為野、為寧，震為歸，《詩衛風》：&quot;遠送於野，泣涕如雨&quot;，莊薑送戴媯，歸國之詩。○悅，宋元本作快，咎作子，均依汲古。</p><h3 id="萃之剝" tabindex="-1">萃之剝 <a class="header-anchor" href="#萃之剝" aria-label="Permalink to “萃之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>三宿無主，南行勞苦。東裡失利，喪其珍寶。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為宿，正互三坤，故曰三宿。震為主，震覆，故無主。坤為勞苦，乾為行，位南，故曰南行。乾為金玉，故曰珍寶。乾伏，故喪其珍寶。坤為裡。東象，或取納乙。</p><h3 id="萃之復" tabindex="-1">萃之復 <a class="header-anchor" href="#萃之復" aria-label="Permalink to “萃之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>大斧破木，讒佞破國。東關梁五，禍及三子。晉人亂危，懷公出走。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《臨》。兌為斧，兌形長故曰大斧。梁五，宋本作東間良王，汲古作良工，依元本。危，汲古訛邑，依宋元本。</p><h3 id="萃之無妄" tabindex="-1">萃之無妄 <a class="header-anchor" href="#萃之無妄" aria-label="Permalink to “萃之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>乘風上天，為時服軒。周旋萬裡，無有患難。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>巽為風，乾為天，艮為時，震為軒、為周旋，乾為萬裡。</p><h3 id="萃之大畜" tabindex="-1">萃之大畜 <a class="header-anchor" href="#萃之大畜" aria-label="Permalink to “萃之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>大樹百根，北與山連。文君作人，受福萬年。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為木，乾大，故曰大樹。乾為百，艮山，伏坤為北，故曰北與山連。坤為文，乾君，故曰文君。震為人、為福，乾為萬年，言文王作人也。○北，汲古作比，人作義，均依宋元。</p><h3 id="萃之頤" tabindex="-1">萃之頤 <a class="header-anchor" href="#萃之頤" aria-label="Permalink to “萃之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>陽伏在下，陰制佑福。生不逢時，潛龍隱處。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>陽在初，故曰伏在下。坤為陰，震為福佑、為生，艮為時，坤閉，故不逢時。震為龍，乾初九曰潛龍勿用，故曰隱處。</p><h3 id="萃之大過" tabindex="-1">萃之大過 <a class="header-anchor" href="#萃之大過" aria-label="Permalink to “萃之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>亂頭多憂，搔蝨生愁。膳夫仲允，使我無聊。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾為頭，伏坤為亂、為憂，巽為蝨，伏艮為搔，伏震為夫、為餌，故曰膳夫。互大坎為仲，乾為信，故曰仲允。伏坤為我，《詩小雅十月篇》：&quot;仲允膳夫&quot;註：皆用後嬖進助幽王亂國者。○搔，丁雲宜依《御覽》作蚤，按：蚤不生頭上，不可從。聊，元本作憂，以與愁韻，豈知聊愁古同韻，易林每如此，故依宋本、汲古。</p><h3 id="萃之坎" tabindex="-1">萃之坎 <a class="header-anchor" href="#萃之坎" aria-label="Permalink to “萃之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>江河淮海，天之都市。商人受福，國家富有。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《小畜》。</p><h3 id="萃之離" tabindex="-1">萃之離 <a class="header-anchor" href="#萃之離" aria-label="Permalink to “萃之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>泰山幽谷，鳳凰遊宿。禮義有序，可以求福。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。互艮為山，震東，故曰泰山。艮為谷，與坎連，故曰幽谷。離為文、為鳳凰，坎為宿，離為夏、為禮，兌為秋、為義，艮求，震福。</p><h3 id="萃之鹹" tabindex="-1">萃之鹹 <a class="header-anchor" href="#萃之鹹" aria-label="Permalink to “萃之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>山水暴怒，壞梁折柱。稽難行旅，留連愁苦。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《鹹》之《豫》。山水，汲古作水山，依宋元本。</p><h3 id="萃之恆" tabindex="-1">萃之恆 <a class="header-anchor" href="#萃之恆" aria-label="Permalink to “萃之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>阿衡服箱，大一載行。巡時厯舍，所之吉昌。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《恆》之《復》。</p><h3 id="萃之遯" tabindex="-1">萃之遯 <a class="header-anchor" href="#萃之遯" aria-label="Permalink to “萃之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>三宿無主，南行勞苦。東裡失利，喪其珍寶。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳本林《剝》。</p><h3 id="萃之大壯" tabindex="-1">萃之大壯 <a class="header-anchor" href="#萃之大壯" aria-label="Permalink to “萃之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>生無父母，出門不喜。買菽失粟，亡我大利。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為生，乾數無，坤伏，兌折，故生無父母。乾為門戶，震出，震喜，父母毀折故不喜。震為菽豆，巽為粟、為利，巽伏，故失粟，故無利。○菽，汲古、元本作椒，依宋本。利，宋元本作乘，依汲古。</p><h3 id="萃之晉" tabindex="-1">萃之晉 <a class="header-anchor" href="#萃之晉" aria-label="Permalink to “萃之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>安坐玉堂，聰樂行觴。飲福萬歲，日壽無疆。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《升》。歲，汲古作鍾，壽作受，依宋元本。</p><h3 id="萃之明夷" tabindex="-1">萃之明夷 <a class="header-anchor" href="#萃之明夷" aria-label="Permalink to “萃之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>登危入厄，四時變易。春霜夏雪，物皆凋落。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為登，伏巽為入，坎危，坤厄，震為春，南為夏，坎為冬，坤為秋，故曰四時變易。震又為時，卦數四也。坤為霜，與震連，故曰春霜。坎為雪，與離連，故曰夏雪。坤為死，故物皆凋落。○夏，宋元本作變，非，依汲古。</p><h3 id="萃之家人" tabindex="-1">萃之家人 <a class="header-anchor" href="#萃之家人" aria-label="Permalink to “萃之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>衣穴履穿，無以禦寒。細小貧窶，不能自存。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>震為衣履，震伏巽，下斷故曰穴、曰穿。坎為寒，離虛，故曰貧窶。○穴，汲古作空，依宋元本。</p><h3 id="萃之睽" tabindex="-1">萃之睽 <a class="header-anchor" href="#萃之睽" aria-label="Permalink to “萃之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>目不可合，憂來搔足。怵惕恐懼，去其邦域。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>睽，《說文》：兩目不相聽也，不相聽故目不可合。坎為憂、為恐懼，艮為邦域，艮伏，故去其邦域。</p><h3 id="萃之蹇" tabindex="-1">萃之蹇 <a class="header-anchor" href="#萃之蹇" aria-label="Permalink to “萃之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>齎貝贖狸，不聽我詞。繫於虎鬚，牽不得來。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為貝、為狸、為虎、為須、為牽，離為有言，故不聽我詞。坎陷，艮止，故牽不得來。</p><h3 id="萃之解" tabindex="-1">萃之解 <a class="header-anchor" href="#萃之解" aria-label="Permalink to “萃之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存，聲芳後時。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《乾》。</p><h3 id="萃之損" tabindex="-1">萃之損 <a class="header-anchor" href="#萃之損" aria-label="Permalink to “萃之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>張王子季，爭財相制。商君頑囂，不知所由。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為張、為王，艮為季，坤為財，正反艮故曰爭財相制。震為君、為商旅，故曰商君。兌魯，故曰頑囂。正反震故不知所由。○由囂為韻，宋元本作申，依汲古。</p><h3 id="萃之益" tabindex="-1">萃之益 <a class="header-anchor" href="#萃之益" aria-label="Permalink to “萃之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>長城既立，四夷賓服。交和結好，昭君是福。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為城，巽為長，故曰長城。坤為夷，震卦數四，故曰四夷。震為賓客，故曰賓服。震喜，正反震，故曰交和結好。震為君，坤為文，艮為明，故曰昭君。顧寧人謂昭君為王嬙，豈知《萃》之《臨》曰昭君守國，《鼎》之《噬嗑》曰昭君喪居，皆因卦有坤離之象，固非指王嬙也。</p><h3 id="萃之夬" tabindex="-1">萃之夬 <a class="header-anchor" href="#萃之夬" aria-label="Permalink to “萃之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>千歡萬悅，舉事為決。獲受嘉慶，動作有得。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>兌為歡悅、為決，乾為千萬。</p><h3 id="萃之姤" tabindex="-1">萃之姤 <a class="header-anchor" href="#萃之姤" aria-label="Permalink to “萃之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>種一得十，日益有息。仁政獲民，四國睦親。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>姤伏復，一陽下生，坤數十，故曰種一得十。復陽日息。震為仁，坤為政、為國、為民，震卦數四，故曰四國。復出入無疾，故睦親。○睦親，汲古作親睦，依宋元本。</p><h3 id="萃之萃" tabindex="-1">萃之萃 <a class="header-anchor" href="#萃之萃" aria-label="Permalink to “萃之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>蒙慶受福，有所獲得。不利出域，病人困棘。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>伏震為福慶，艮止，故有獲，故不利出域。艮為域，互大坎為病、為棘。○域，汲古作城，病棘作疾極，依宋元本。</p><h3 id="萃之升" tabindex="-1">萃之升 <a class="header-anchor" href="#萃之升" aria-label="Permalink to “萃之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>安子富有，東國不殃。齊鄭和親，顯比以喜。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為安、為富有，震為子，故曰安子富有。坤為國、為殃，震為東，震解，故曰東國不殃。巽為齊，坤為鄭。《說文》：&quot;鄭，地町町然平也&quot;，故坤形象之。兌悅，故和親。坤為比，震為喜。○以，宋元本作不，依汲古。安子事未詳。</p><h3 id="萃之困" tabindex="-1">萃之困 <a class="header-anchor" href="#萃之困" aria-label="Permalink to “萃之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>九里十山，道仰峻難。牛馬不前，復反來還。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。震數九，兌數十，艮為裡、為山，故曰九里十山。艮為道，艮高，故曰峻難。離為牛，震為馬，艮止，故不前。震反，故曰還。</p><h3 id="萃之井" tabindex="-1">萃之井 <a class="header-anchor" href="#萃之井" aria-label="Permalink to “萃之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>鳩杖扶老，衣食百口。曾孫壽考，兇惡不起。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>《風俗通》高祖戰敗，匿叢薄間，鳩鳴其上，因得脫，後作鳩杖，以賜老者。離為鳩，巽為杖，伏艮為扶、為壽，故曰扶老。兌為食、為口，上下卦正反皆有口形，故曰百口。又伏震為百也。艮為曾孫、為壽考。○曾孫，宋元本作增添，依汲古。</p><h3 id="萃之革" tabindex="-1">萃之革 <a class="header-anchor" href="#萃之革" aria-label="Permalink to “萃之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>霧露雪霜，日暗不明。陰孽為疾，年穀大傷。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《恆》。</p><h3 id="萃之鼎" tabindex="-1">萃之鼎 <a class="header-anchor" href="#萃之鼎" aria-label="Permalink to “萃之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>迷行數卻，不知東西。陰強暴逆，道里不通。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為迷、為退，故數卻，故不知東西。震為東，兌為西也。坤為陰、為逆，震為大塗，坎陷，故不通。○裡，宋元、汲古皆作理，依局本。</p><h3 id="萃之震" tabindex="-1">萃之震 <a class="header-anchor" href="#萃之震" aria-label="Permalink to “萃之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>登高上山，見王自言。信理我冤，得職蒙恩。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為登，艮為山，故曰登高上山。震為伸、為王、為言，坎為冤，震解，故曰伸理我冤。艮為官職。</p><h3 id="萃之艮" tabindex="-1">萃之艮 <a class="header-anchor" href="#萃之艮" aria-label="Permalink to “萃之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>三世為德，天祚以國。封建少昊，魯侯之福。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為世，納丙，故曰三世。艮為天、為國，互震為德，艮為封建，震為帝，故曰少昊。伏兌為魯，震為諸侯、為福。魯國為少昊之墟，言周公佐文王、武王、成王，有功於三世，故得建國於少昊之虛也。</p><h3 id="萃之漸" tabindex="-1">萃之漸 <a class="header-anchor" href="#萃之漸" aria-label="Permalink to “萃之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>喬木無息，漢女難得。橘柚請佩，反手難悔。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>《詩周南》：&quot;南有喬木，不可休息；漢有遊女，不可求思&quot;，《列仙傳》：&quot;江泛二女，鄭交甫悅之，下請其橘柚之佩，遂解佩與交甫，交甫受而懷之，去數十步，佩亡，二女亦不見&quot;，黃丕烈雲《韓詩內傳》亦載此事，所謂聘之以橘柚也，然則此事相傳甚古，詩詞是否指此誠不敢定，然焦韓二家則皆與列仙傳同也。巽為木、為高，故曰喬木。震為息，震伏，故曰無息。坎水，巽女，故曰漢女。艮為橘柚、為手、為佩，伏震為反艮，故曰反手難悔。言一釋手即無也。○喬，元本作橘，依宋本、汲古。橘柚，汲古訛禱神，難悔作離汝，均依宋元本。</p><h3 id="萃之歸妹" tabindex="-1">萃之歸妹 <a class="header-anchor" href="#萃之歸妹" aria-label="Permalink to “萃之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>東鄰西家，來即我謀。中告吉誠，使君安寧。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>離為東鄰，坎為西鄰、為謀、為中、為誠，震為告、為君，伏艮為安寧。</p><h3 id="萃之豐" tabindex="-1">萃之豐 <a class="header-anchor" href="#萃之豐" aria-label="Permalink to “萃之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>褰衣出戶，心欲北走。王孫母驚，使我長生。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。艮為褰、為戶，震為衣、為出走，故曰褰衣出戶。坎為心、為北，故曰心欲北走。震為王，艮為孫、為我，震為生、為驚，巽長，故曰長生。○北，汲古作奔，依宋元本。</p><h3 id="萃之旅" tabindex="-1">萃之旅 <a class="header-anchor" href="#萃之旅" aria-label="Permalink to “萃之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>三日不飲，遠水無酒。晝夜焦喉，使我為咎。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>離日，艮數三，故曰三日。兌口為飲，艮止，故曰不飲。坎為水、為酒，坎伏在山上，故曰遠水無酒。離為晝，坎為夜，兌為喉，上離火、下艮火，故焦喉。○使我，宋元本作傷鬼，依汲古。</p><h3 id="萃之巽" tabindex="-1">萃之巽 <a class="header-anchor" href="#萃之巽" aria-label="Permalink to “萃之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>眾口銷金，愆言不驗。腐臭敗兔，入市不售。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>初四正反兌，故曰眾口。乾為金，一陰下生銷陽，故曰銷金。正反兌，故曰愆者，言愆者，差也，爽也。巽為臭腐，伏震為兔，巽爛，故曰敗兔。巽為入、為市。</p><h3 id="萃之兌" tabindex="-1">萃之兌 <a class="header-anchor" href="#萃之兌" aria-label="Permalink to “萃之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>姬冠應門，與伯爭言。東家失狗，意我不存。爭亂忘因，絕其所歡。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏艮。互震為姬、為伯，艮為門，三至上正反震，故曰應門、曰爭言。震為東，艮為狗，艮伏，故曰失狗。坎為意，艮為我。意我不存者，意我有無也，不謂無，存謂有。○我，汲古作在，忘因作無怠，其作吾，均依宋元本。姬疑為雞之音訛字，巽為雞。易林亦以兌為雞，《史記孔子弟子列傳》：&quot;子路好勇，冠雞冠&quot;。惟，汲古作嫗，似又與伯對文，茲姑從宋元本。</p><h3 id="萃之渙" tabindex="-1">萃之渙 <a class="header-anchor" href="#萃之渙" aria-label="Permalink to “萃之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>祚加明德，興我周國。公劉文母，福流子孫。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為明，震為周、為德、為公，伏離為文，巽為母。公劉，周祖文母大任也。《詩》：&quot;恩齊太任，文王之母&quot;。震為福、為子，艮為孫。○興，汲古作與，依宋元本。</p><h3 id="萃之節" tabindex="-1">萃之節 <a class="header-anchor" href="#萃之節" aria-label="Permalink to “萃之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>針頭刺手，百病瘳愈。抑按捫灸，死人復起。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坎為針、為刺，艮為手、為頭，故曰針頭刺手。坎為病，震為百，震解，故瘳愈。艮為按捫。艮火，故曰灸。震為人、為起，坎為死，故曰死人復起。</p><h3 id="萃之中孚" tabindex="-1">萃之中孚 <a class="header-anchor" href="#萃之中孚" aria-label="Permalink to “萃之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>元龜象齒，大賂為寶。稽疑當否，衰微復起。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為龜、為象，震長，故曰元龜。兌為齒，震為寶，龜可卜，故曰稽疑。正反艮，故曰當否。巽隕落，故曰衰微。震為起。《詩魯頌》：&quot;元龜象齒，大賂南金&quot;。</p><h3 id="萃之小過" tabindex="-1">萃之小過 <a class="header-anchor" href="#萃之小過" aria-label="Permalink to “萃之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>故室舊廬，消散無餘。不如新創，可以樂居。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>上二句說上卦震，震為覆艮，艮為室、為廬，艮覆，故曰消散。下二句說下艮，艮手為創、為居，形儼然新屋，震喜，故曰樂居。</p><h3 id="萃之既濟" tabindex="-1">萃之既濟 <a class="header-anchor" href="#萃之既濟" aria-label="Permalink to “萃之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>老狐多態，行為蠱怪。驚我王母，終無咎悔。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>多用半象。汲古本怪下多為魅為妖四字，依宋元本。</p><h3 id="萃之未濟" tabindex="-1">萃之未濟 <a class="header-anchor" href="#萃之未濟" aria-label="Permalink to “萃之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>愛子多財，起跡空虛。避害如神，水不能濡。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>多用半象。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
